using System.Collections.Frozen;

namespace Agnosia.Models;

public sealed record AppPermissionText(string Label, string Description);

/// <summary>
/// User-facing Russian explanations for verified Android and common app permissions.
/// The requested permission list and grant state still come from Android.
/// Unrecognized platform, vendor, and application-defined permissions have no guessed text.
/// </summary>
public static class AppPermissionDictionary
{
    public const string UnknownLabel = "Неизвестное разрешение";

    private static readonly FrozenDictionary<string, AppPermissionText> Entries = Build();

    public static AppPermissionText? Find(string name) => Entries.GetValueOrDefault(name);

    public static int Count => Entries.Count;

    private static FrozenDictionary<string, AppPermissionText> Build()
    {
        var entries = new Dictionary<string, AppPermissionText>(StringComparer.Ordinal);
        foreach (var line in Data.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            var parts = line.Split('|', StringSplitOptions.TrimEntries);
            if (parts.Length != 3 || parts.Any(string.IsNullOrWhiteSpace))
                throw new InvalidOperationException($"Некорректная запись словаря разрешений: {line}");
            var name = parts[0].Contains('.') ? parts[0] : $"android.permission.{parts[0]}";
            entries.Add(name, new AppPermissionText(parts[1], parts[2]));
        }
        AppHealthPermissionDictionary.AddTo(entries);
        return entries.ToFrozenDictionary(StringComparer.Ordinal);
    }

